// fayl: lib/markdown.ts
export function mdToHtml(md: string) {
  return md
    .split("\n")
    .map((line) =>
      line.startsWith("## ") ? `<h2>${line.slice(3)}</h2>` : line.startsWith("- ") ? `<li>${line.slice(2)}</li>` : `<p>${line}</p>`,
    )
    .join("")
    .replace(/\*\*(.+?)\*\*/g, "<b>$1</b>")
}

