const orders = [
  { city: "Toshkent", total: 50000 },
  { city: "Xiva", total: 30000 },
  { city: "Toshkent", total: 20000 },
  { city: "Buxoro", total: 45000 },
]

export default function Report() {
  const byCity = Object.entries(
    orders.reduce<Record<string, number>>((acc, o) => ({ ...acc, [o.city]: (acc[o.city] ?? 0) + o.total }), {}),
  ).sort((a, b) => b[1] - a[1])
  return (
    <ol>
      {byCity.map(([city, sum]) => (
        <li key={city}>{city}: {sum.toLocaleString("ru-RU")}</li>
      ))}
    </ol>
  )
}

