"use client"
import { useReducer } from "react"

type Action = { type: "add"; item: string } | { type: "remove"; item: string } | { type: "clear" }

function reducer(state: Record<string, number>, a: Action) {
  switch (a.type) {
    case "add":
      return { ...state, [a.item]: (state[a.item] ?? 0) + 1 }
    case "remove": {
      const { [a.item]: _, ...rest } = state
      return rest
    }
    case "clear":
      return {}
  }
}

export function Cart() {
  const [cart, dispatch] = useReducer(reducer, {})
  return (
    <div>
      <button onClick={() => dispatch({ type: "add", item: "non" })}>+ non</button>
      <button onClick={() => dispatch({ type: "add", item: "choy" })}>+ choy</button>
      <button onClick={() => dispatch({ type: "remove", item: "non" })}>− non</button>
      <p>{JSON.stringify(cart)}</p>
    </div>
  )
}

