"use client"
import { useMemo, useState } from "react"

let computations = 0

export function Primes() {
  const [limit, setLimit] = useState(1000)
  const [dark, setDark] = useState(false)
  const count = useMemo(() => {
    computations++
    let c = 0
    for (let n = 2; n <= limit; n++) {
      let prime = true
      for (let d = 2; d * d <= n; d++) if (n % d === 0) { prime = false; break }
      if (prime) c++
    }
    return c
  }, [limit])
  return (
    <div>
      <p>{limit} gacha tub sonlar: {count}</p>
      <p>Hisoblashlar: {computations}</p>
      <button onClick={() => setDark(!dark)}>Mavzu: {dark ? "qora" : "oq"}</button>{" "}
      <button onClick={() => setLimit(limit * 10)}>Chegarani ×10</button>
    </div>
  )
}

