// fayl: app/Checklist.tsx
"use client"
import { useState } from "react"

const items = ["Guruch", "Go'sht", "Sabzi"]

export function Checklist() {
  const [checked, setChecked] = useState(new Set<string>())
  const toggle = (i: string) => {
    const next = new Set(checked)
    next.has(i) ? next.delete(i) : next.add(i)
    setChecked(next)
  }
  const all = checked.size === items.length
  return (
    <div>
      <label><input type="checkbox" checked={all} onChange={() => setChecked(all ? new Set() : new Set(items))} /> Hammasi</label>
      {items.map((i) => (
        <label key={i}><input type="checkbox" checked={checked.has(i)} onChange={() => toggle(i)} /> {i}</label>
      ))}
      <p>Tanlangan: {checked.size}/{items.length}</p>
    </div>
  )
}

