"use client"
import { useEffect, useState } from "react"

export function LiveSearch() {
  const [q, setQ] = useState("")
  const [results, setResults] = useState<string[]>([])

  useEffect(() => {
    if (!q) return
    const controller = new AbortController()
    fetch(`/api/search?q=${encodeURIComponent(q)}`, { signal: controller.signal })
      .then((res) => res.json())
      .then(setResults)
      .catch((e) => {
        if (e.name !== "AbortError") throw e   // bekor qilish xato emas
      })
    return () => controller.abort()            // q o'zgarsa, eski so'rov to'xtatiladi
  }, [q])

  return (
    <div>
      <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Taom" />
      <p>{q ? results.join(", ") : "Taom nomini yozing"}</p>
    </div>
  )
}

