// fayl: app/cart-context.tsx
"use client"
import { createContext, useContext, useState } from "react"

type Item = { name: string; qty: number }
type Cart = { items: Item[]; add: (name: string) => void }

const CartContext = createContext<Cart | null>(null)

export function CartProvider({ initialItems, children }: { initialItems: Item[]; children: React.ReactNode }) {
  const [items, setItems] = useState(initialItems)
  const add = (name: string) =>
    setItems((cur) =>
      cur.some((i) => i.name === name)
        ? cur.map((i) => (i.name === name ? { ...i, qty: i.qty + 1 } : i))
        : [...cur, { name, qty: 1 }],
    )
  return <CartContext.Provider value={{ items, add }}>{children}</CartContext.Provider>
}

export function useCart() {
  const cart = useContext(CartContext)
  if (!cart) throw new Error("useCart faqat CartProvider ichida ishlaydi")
  return cart
}

