// fayl: app/Rates.tsx
import { connection } from "next/server"

// sekin tashqi xizmat: 5 soniyada javob beradi, signal kelsa to'xtaydi
function slowService(signal: AbortSignal): Promise<{ usd: number }> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => resolve({ usd: 12650 }), 5000)
    signal.addEventListener("abort", () => {
      clearTimeout(timer)
      reject(signal.reason)
    })
  })
}

async function getRates(): Promise<{ usd: number } | null> {
  await connection()
  try {
    return await slowService(AbortSignal.timeout(1500))   // 1,5 soniyadan keyin bekor qilinadi
  } catch {
    return null                                           // vaqt tugadi yoki xizmat yiqildi
  }
}

export async function Rates() {
  const rates = await getRates()
  return <p>{rates ? `USD: ${rates.usd} so'm` : "Kurs vaqtincha mavjud emas"}</p>
}

