// fayl: app/Tabs.tsx
"use client"
import { Suspense, use, useState, useTransition } from "react"

const cache = new Map<string, Promise<string>>()

function loadTab(name: string) {
  if (!cache.has(name)) {
    cache.set(name, new Promise((resolve) => setTimeout(() => resolve(`${name} bo'limi tayyor`), 500)))
  }
  return cache.get(name)!                    // bir xil Promise — React uni qayta kuta oladi
}

function Panel({ name }: { name: string }) {
  return <p>{use(loadTab(name))}</p>
}

export function Tabs() {
  const [tab, setTab] = useState("Masalliqlar")
  const [pending, startTransition] = useTransition()
  return (
    <div>
      {["Masalliqlar", "Izohlar"].map((name) => (
        <button key={name} onClick={() => startTransition(() => setTab(name))}>{name}</button>
      ))}
      <div style={{ opacity: pending ? 0.5 : 1 }}>
        <Suspense fallback={<p>⏳ Yuklanmoqda...</p>}>
          <Panel name={tab} />
        </Suspense>
      </div>
    </div>
  )
}

