export async function getTodo() {
  "use cache"
  cacheLife("hours")
  cacheTag("todo")
  const res = await fetch("https://jsonplaceholder.typicode.com/todos/1")
  return (await res.json()) as { title: string }
}

// fayl: app/todo/page.tsx
