// fayl: app/search/page.tsx
import { Suspense } from "react"
import { cacheLife } from "next/cache"

async function searchRecipes(query: string | string[] | undefined) {
  "use cache"
  cacheLife("minutes")
  return [`${query ?? "hammasi"}: Palov`, `${query ?? "hammasi"}: Manti`]
}

async function Results({
  searchParams,
}: Pick<PageProps<"/search">, "searchParams">) {
  const { q } = await searchParams
  const results = await searchRecipes(q)
  return <ul>{results.map((r) => <li key={r}>{r}</li>)}</ul>
}

export default function SearchPage(props: PageProps<"/search">) {
  return (
    <main>
      <h1>Qidiruv</h1>
      <Suspense fallback={<p>Qidirilmoqda...</p>}>
        <Results searchParams={props.searchParams} />
      </Suspense>
    </main>
  )
}

